class Solution {
public:
    vector<int> solve(string s,unordered_map<string,vector<int>> &ump)
    {
        vector<int> res;
        int n=s.size();
        for(int i=0;i<n;i++)
        {
            if(s[i]=='+' or s[i]=='-' or s[i]=='*')
            {
                vector<int> res1,res2;
                string temp=s.substr(0,i);
                if(ump.find(temp)!=ump.end())
                    res1=ump[temp];
                else
                    res1=solve(temp,ump);
                temp=s.substr(i+1);
                if(ump.find(temp)!=ump.end())
                    res2=ump[temp];
                else
                    res2=solve(temp,ump);
                for(auto it1:res1)
                {
                    for(auto it2:res2)
                    {
                        if(s[i]=='+')
                            res.push_back(it1+it2);
                        else if(s[i]=='-')
                            res.push_back(it1-it2);
                        else
                            res.push_back(it1*it2);
                    }
                }
            }
        }
        if(res.empty())
            res.push_back(atoi(s.c_str()));
        ump[s]=res;
        return res;
    }
    vector<int> diffWaysToCompute(string s) {
        unordered_map<string,vector<int>> ump;
        return solve(s,ump);
    }
};

from collections import defaultdict
from itertools import product
import re
class Solution:
    # @param {string} input
    # @return {integer[]}
    def diffWaysToCompute(self, input):
        self.s = ''.join([c for c in input if c!=" "])
        self.items = re.findall("\+|\-|\*|[0-9]+", self.s)
        l = len(self.items)
        self.memo = defaultdict(set)
        self.visit(0, l-1)
        return list(self.memo[(0, l-1)])

    def visit(self, left, right):
    	if (left, right) in self.memo:
    		return self.memo[(left, right)]
    	if left == right:
    		self.memo[(left, right)]=[int(self.items[left])]
    		return self.memo[(left, right)]
    	else:
    		_set = []
    		operator_idx = left + 1
    		while operator_idx < right:
    			operator = self.items[operator_idx]
    			set1 = self.visit(left, operator_idx-1)
    			set2 = self.visit(operator_idx+1, right)
    			for a, b in product(set1, set2):
    				if operator == '+':
    					_set.append(a+b)
    				elif operator == '-':
    					_set.append(a-b)
    				elif operator == '*':
    					_set.append(a*b)
    			operator_idx += 2
    		self.memo[(left, right)] = _set
    		return _set

class Solution(object):
    def diffWaysToCompute(self, input):
        """
        :type input: str
        :rtype: List[int]
        """
        tokens = []
        num = 0
        for c in input:
            if c in "+-*":
                tokens.append(num)
                num = 0
                tokens.append(c)
            else:
                num = num*10+ord(c)-ord('0')
        tokens.append(num)

        rset = self._recurse(tokens)
        return sorted(list(rset))

    def _recurse(self, tokens):
        if len(tokens)==1:
            return [tokens[0]]
        # for each operator, split
        result = []
        for i, c in enumerate(tokens):
            if isinstance(c, int): continue
            if c in "+-*":
                left = self._recurse(tokens[:i])
                right = self._recurse(tokens[i+1:])
                # get the product of 2 subparts
                for l in left:
                    for r in right:
                        if c=="+":
                            result.append(l+r)
                        elif c=="-":
                            result.append(l-r)
                        else:
                            result.append(l*r)
        return result

class Solution(object):
    def diffWaysToCompute(self, expression):
        """
        :type expression: str
        :rtype: List[int]
        """
        if expression.isdigit():
            return [int(expression)]

        ans = []
        for i, c in enumerate(expression):
            if c in ["+", "-", "*"]:
                left = self.diffWaysToCompute(expression[:i])
                right = self.diffWaysToCompute(expression[i + 1:])
                for t1 in left:
                    for t2 in right:
                        if c == "+":
                            ans.append(t1 + t2)
                        elif c == "-":
                            ans.append(t1 - t2)
                        else:
                            ans.append(t1 * t2)
        return ans
